function App() {
  const [voterHash, setVoterHash] = useState("");
  const [token, setToken] = useState(() => localStorage.getItem("adminToken") || "");

  const handleSetToken = (newToken) => {
    setToken(newToken);
    if (newToken) {
      localStorage.setItem("adminToken", newToken);
    } else {
      localStorage.removeItem("adminToken");
    }
  };

  return (
    <Router>
      <Routes>
        <Route path="/" element={<VoterVerify setVoterHash={setVoterHash} />} />
        <Route path="/ballot" element={<BallotPage voterHash={voterHash} />} />
        <Route path="/success" element={<VoteSuccess />} />
        <Route path="/admin" element={<AdminLogin setToken={handleSetToken} />} />
        <Route path="/results" element={<ResultsPage token={token} handleLogout={() => handleSetToken("")} />} />
      </Routes>
    </Router>
  );
}
